
const portfolioDrawings = {"assets/retail-layout.pdf": "", "assets/expanded/retail-sections.pdf": "", "assets/bazaar-layout.pdf": "", "assets/food-kiosk.pdf": "", "assets/expanded/prefab-joinery.pdf": "", "assets/expanded/exit-layout.pdf": "", "assets/expanded/rural-residence.pdf": "", "assets/retail-electrical.pdf": "", "assets/expanded/residential-services.pdf": "", "assets/expanded/media-joinery.pdf": "", "assets/expanded/compact-floor-layout.pdf": "", "assets/cafe-fitout.pdf": "", "assets/expanded/booth-framing.pdf": "", "assets/expanded/rural-house-plans.pdf": "", "assets/expanded/prefab-services.pdf": "", "assets/house-renovation.pdf": "", "assets/tenant-fitout.pdf": "", "assets/expanded/cladding-plan.pdf": "", "assets/expanded/wardrobe-detail.pdf": "", "assets/expanded/branch-renovation.pdf": ""};
document.addEventListener("DOMContentLoaded", () => {
  for (const link of document.querySelectorAll("a[href]")) {
    const encoded = portfolioDrawings[link.getAttribute("href")];
    if (!encoded) continue;
    const bytes = Uint8Array.from(atob(encoded), character => character.charCodeAt(0));
    link.href = URL.createObjectURL(new Blob([bytes], { type: "application/pdf" }));
  }
});
